#!/usr/bin/env bash
# T1c-ROOD (decision 63, H2 design (A); preregistration.md in this folder): exact queue commands. NOT EXECUTED by
# the agent. Printed by `python -m vsa_embed.experiments.t1c_rood plan`. Run from the main checkout's root after merging:
#   cd /home/bhux/workplace/VSA-LLM && PY=/home/bhux/anaconda3/envs/vsa-repro/bin/python
# The CPU stages (select, prepare, build, alias-table) have run; their outputs are under ~/data/vsa-llm/t1c/rood-v1/
# and ~/data/vsa-llm/t1c/e9/t1c-rood.json (shared by every checkout).
# Run order (author, 2026-10-08; decisive first): 54.4998 frozen-host (P0-360M) encode, coding and R1 analysis;
# 54.49981 E9 training (seeds 1–3); 54.49982 coding on the ROOD-trained C0' / C5 and the rescoring;
# 54.49983 the remaining analyses; 54.49984 reports. Equal priorities run in creation order: run this file top to bottom.
# GPU-h: idle-GPU estimates from measured costs — E9 SmolLM2-360M ≈ 67 min per 50M-token run plus its 2,048-window
# evaluations (e9_plan --dry-run); T1c-F's smoke-scaled encode 1.5 / 1.7 GPU-h and head training ≈ 0.8 GPU-h per
# 7-condition seed (ROOD trains on 84% of T1c-F's admissions; free_mean / free_zero add two scoring passes); e4_quant
# ≈ 0.25 GPU-h per pass of 21,827 windows (T1c-2). Total ≈ 25.4 GPU-h.
set -euo pipefail
: "${PY:?set PY to the pinned interpreter}"

# --- 1. at 54.4998: coding on P0 (frozen SmolLM2-360M, never saw MIMIC), the primary encoder, and R1. The encode
# reuses T1c-F's P0 states (t1cf-encode-P0-360M, 54.41) only when their manifest matches exactly (host, token store
# and truncation, chunking, precision, admission order): it then writes only REUSED.json under rood-v1/coding and
# costs nothing. Absent, incomplete or older (unrecorded fields) states → it encodes into rood-v1/coding/states;
# a definite mismatch fails loudly. It never writes T1c-F's states, and T1c-F's job never reads ROOD's. ≈ 3.9 GPU-h (≈ 2.4 on reuse) ---
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-encode-P0-360M --priority 54.4998 --min-free-gb 20 -- $PY -m vsa_embed.experiments.t1c_icd_frequency encode --config experiments/t1c-clinical/rood/rood.yaml --encoder P0-360M --pretrained HuggingFaceTB/SmolLM2-360M --reuse-base   # 0 on reuse, else ≈ 1.5 GPU-h (resumable)
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-train-P0-360M-s1 --priority 54.4998 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/rood/rood.yaml --encoder P0-360M --seed 1   # 7 conditions + free_mean / free_zero ≈ 0.75 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-train-P0-360M-s2 --priority 54.4998 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/rood/rood.yaml --encoder P0-360M --seed 2   # 7 conditions + free_mean / free_zero ≈ 0.75 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-train-P0-360M-s3 --priority 54.4998 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/rood/rood.yaml --encoder P0-360M --seed 3   # 7 conditions + free_mean / free_zero ≈ 0.75 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-analyze-P0-360M --priority 54.4998 --min-free-gb 2 --no-resume -- $PY -m vsa_embed.experiments.t1c_rood analyze --config experiments/t1c-clinical/rood/rood.yaml --encoder P0-360M --seeds 1 2 3 --device cuda   # R1 (primary) ≈ 0.10 GPU-h

# --- 2. at 54.49981: E9 on the ROOD corpus (track t1c-rood): SmolLM2-360M P0 / C0' / C2 / C5 × seeds 1–3, training
# only (no per-run probe / item evaluations: T1c's items are built on its own holdout, trained here). ≈ 10.5 GPU-h ---
PYTHONPATH=src $PY -m vsa_embed.experiments.e9_plan --track t1c-rood --stage t1c-rood --hosts SmolLM2-360M --models P0 C0p C2 C5 --seeds 1 2 3 --no-evals --priority 54.49981 --level-step 0.00001 --queue

# --- 3. at 54.49982: coding on the ROOD-trained encoders (E9 seed 1: SmolLM2-360M-full-C0p-s1, SmolLM2-360M-full-C5-s1): their encodes,
# 8 conditions (composed_c5 = the C5-ROOD composer; ROOD concepts never linked in its training) and composed_c5 on
# P0 (≈ 8.9 GPU-h); L1 on the whole eval-rood split (4865 windows; e4_quant ref + INT8-A; P0, C0', C2, C5
# × 3 seeds) and the locality check on eval-general (C3's documents, the runs' 2,048 windows) (≈ 1.6 GPU-h) ---
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-encode-C0p-ROOD-360M --priority 54.49982 --min-free-gb 20 -- $PY -m vsa_embed.experiments.t1c_icd_frequency encode --config experiments/t1c-clinical/rood/rood.yaml --encoder C0p-ROOD-360M --run experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C0p-s1   # ≈ 1.7 GPU-h (resumable)
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-train-C0p-ROOD-360M-s1 --priority 54.49982 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/rood/rood.yaml --encoder C0p-ROOD-360M --seed 1 --conditions free composed_head composed_c5 transe title random gram composed_free --c5-run experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s1   # ≈ 0.85 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-train-C0p-ROOD-360M-s2 --priority 54.49982 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/rood/rood.yaml --encoder C0p-ROOD-360M --seed 2 --conditions free composed_head composed_c5 transe title random gram composed_free --c5-run experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s1   # ≈ 0.85 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-train-C0p-ROOD-360M-s3 --priority 54.49982 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/rood/rood.yaml --encoder C0p-ROOD-360M --seed 3 --conditions free composed_head composed_c5 transe title random gram composed_free --c5-run experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s1   # ≈ 0.85 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-encode-C5-ROOD-360M --priority 54.49982 --min-free-gb 20 -- $PY -m vsa_embed.experiments.t1c_icd_frequency encode --config experiments/t1c-clinical/rood/rood.yaml --encoder C5-ROOD-360M --run experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s1 --channel on   # ≈ 1.7 GPU-h (resumable)
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-train-C5-ROOD-360M-s1 --priority 54.49982 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/rood/rood.yaml --encoder C5-ROOD-360M --seed 1 --conditions free composed_head composed_c5 transe title random gram composed_free --c5-run experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s1   # ≈ 0.85 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-train-C5-ROOD-360M-s2 --priority 54.49982 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/rood/rood.yaml --encoder C5-ROOD-360M --seed 2 --conditions free composed_head composed_c5 transe title random gram composed_free --c5-run experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s1   # ≈ 0.85 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-train-C5-ROOD-360M-s3 --priority 54.49982 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/rood/rood.yaml --encoder C5-ROOD-360M --seed 3 --conditions free composed_head composed_c5 transe title random gram composed_free --c5-run experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s1   # ≈ 0.85 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-train-P0-360M-c5dict-s1 --priority 54.49982 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/rood/rood.yaml --encoder P0-360M --seed 1 --conditions composed_c5 --c5-run experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s1   # ≈ 0.15 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-train-P0-360M-c5dict-s2 --priority 54.49982 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/rood/rood.yaml --encoder P0-360M --seed 2 --conditions composed_c5 --c5-run experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s1   # ≈ 0.15 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-train-P0-360M-c5dict-s3 --priority 54.49982 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency train --config experiments/t1c-clinical/rood/rood.yaml --encoder P0-360M --seed 3 --conditions composed_c5 --c5-run experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s1   # ≈ 0.15 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-quant-rood --priority 54.49982 --min-free-gb 5 -- $PY -m vsa_embed.experiments.e4_quant --runs experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-frozen-P0-s1 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C0p-s1 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C0p-s2 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C0p-s3 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C2-s1 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C2-s2 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C2-s3 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s1 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s2 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s3 --output experiments/e9-retrofit/quant-full/t1c-rood --bits 8 --variants A --baseline "C0'" --references C2 --windows 4865 --resume --title "E9 T1c-ROOD on the whole eval-rood split"
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-quant-general --priority 54.49982 --min-free-gb 5 -- $PY -m vsa_embed.experiments.e4_quant --runs experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-frozen-P0-s1 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C0p-s1 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C0p-s2 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C0p-s3 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C2-s1 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C2-s2 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C2-s3 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s1 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s2 experiments/e9-retrofit/runs/t1c-rood/SmolLM2-360M-full-C5-s3 --output experiments/e9-retrofit/quant-general/t1c-rood --bits 8 --variants A --baseline "C0'" --references C2 --eval-corpus /home/bhux/data/vsa-llm/t1c/rood-v1/lm/eval-general --resume --title "E9 T1c-ROOD on general text"

# --- 4. at 54.49983: the remaining analyses (the bootstrap on the GPU): P0 again with composed_c5 (-pass2; the primary
# contrast is unchanged: its draws do not depend on the other conditions), C0' / C5-ROOD, and T1c-F's endpoints under
# ROOD (descriptive). ≈ 0.5 GPU-h ---
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-analyze-P0-360M-pass2 --priority 54.49983 --min-free-gb 2 --no-resume -- $PY -m vsa_embed.experiments.t1c_rood analyze --config experiments/t1c-clinical/rood/rood.yaml --encoder P0-360M --seeds 1 2 3 --device cuda --label -pass2   # ≈ 0.10 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-analyze-C0p-ROOD-360M --priority 54.49983 --min-free-gb 2 --no-resume -- $PY -m vsa_embed.experiments.t1c_rood analyze --config experiments/t1c-clinical/rood/rood.yaml --encoder C0p-ROOD-360M --seeds 1 2 3 --device cuda   # ≈ 0.10 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-analyze-C5-ROOD-360M --priority 54.49983 --min-free-gb 2 --no-resume -- $PY -m vsa_embed.experiments.t1c_rood analyze --config experiments/t1c-clinical/rood/rood.yaml --encoder C5-ROOD-360M --seeds 1 2 3 --device cuda   # ≈ 0.10 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-analyze-t1cf-P0-360M --priority 54.49983 --min-free-gb 2 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency analyze --config experiments/t1c-clinical/rood/rood.yaml --encoder P0-360M --seeds 1 2 3 --device cuda   # T1c-F's endpoints under ROOD (descriptive)
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-analyze-t1cf-C0p-ROOD-360M --priority 54.49983 --min-free-gb 2 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency analyze --config experiments/t1c-clinical/rood/rood.yaml --encoder C0p-ROOD-360M --seeds 1 2 3 --device cuda   # T1c-F's endpoints under ROOD (descriptive)
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-analyze-t1cf-C5-ROOD-360M --priority 54.49983 --min-free-gb 2 --no-resume -- $PY -m vsa_embed.experiments.t1c_icd_frequency analyze --config experiments/t1c-clinical/rood/rood.yaml --encoder C5-ROOD-360M --seeds 1 2 3 --device cuda   # T1c-F's endpoints under ROOD (descriptive)

# --- 5. at 54.49984 (CPU lane: names contain -report): R9 for the stage, then the ROOD endpoints ---
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-e9-report --priority 54.49984 --min-free-gb 1 --no-resume -- $PY -m vsa_embed.experiments.e9_report --runs experiments/e9-retrofit/runs/t1c-rood --quant experiments/e9-retrofit/quant-full/t1c-rood --quant-general experiments/e9-retrofit/quant-general/t1c-rood --output experiments/e9-retrofit/report/t1c-rood --overwrite   # ≈ 0.4 h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name t1crood-report --priority 54.49984 --min-free-gb 1 --no-resume -- $PY -m vsa_embed.experiments.t1c_rood report --config experiments/t1c-clinical/rood/rood.yaml --encoders P0-360M P0-360M-pass2 C0p-ROOD-360M C5-ROOD-360M --quant experiments/e9-retrofit/quant-full/t1c-rood   # minutes
